(self.webpackChunksite=self.webpackChunksite||[]).push([[117],{1877:t=>{"use strict";t.exports=JSON.parse('{"slug":"wasm-invaders","title":"WASM Invaders","authors":[{"name":"Lorenzo Henrique Zanetti","contact":"lorenzohz","contactType":"github","contactUrl":"https://github.com/lorenzohz"},{"name":"Matheus Cenerini Jacomini","contact":"Mathayuz","contactType":"github","contactUrl":"https://github.com/Mathayuz"}],"date":1752278400000,"readme":"<p>A classic arcade shooter, inspired by the classic Space Invaders and reimagined in C for the fantasy console <a href=\\"https://wasm4.org\\">WASM-4</a>.</p>\\n<p><img src=\\"wasminvaders.png\\" alt=\\"Gameplay Screenshot\\"></p>\\n<h2>Description</h2>\\n<p>Pilot your ship at the bottom of the screen and defend the galaxy against swarms of descendant aliens. Fight through endless waves of invaders that become faster and more numerous with each level. Accumulate a high score and show off your skills in this retro-inspired shooter!</p>\\n<h2>Features</h2>\\n<ul>\\n<li>\\n<p>Endless waves with progressive difficulty.</p>\\n</li>\\n<li>\\n<p>Classic alien formation movement.</p>\\n</li>\\n<li>\\n<p>Score and wave counter in the interface.</p>\\n</li>\\n<li>\\n<p>Particle effects and sounds for action feedback.</p>\\n</li>\\n<li>\\n<p>Animated background with parallax effect.</p>\\n</li>\\n<li>\\n<p>Custom sprites, color palette, and victory jingle.</p>\\n</li>\\n<li>\\n<p>Developed in C, without dependencies on standard libraries.</p>\\n</li>\\n</ul>\\n<h2>Controls</h2>\\n<table>\\n<thead>\\n<tr>\\n<th align=\\"left\\">Action</th>\\n<th align=\\"left\\">Keyboard</th>\\n<th align=\\"left\\">Gamepad</th>\\n</tr>\\n</thead>\\n<tbody>\\n<tr>\\n<td align=\\"left\\">Move Ship</td>\\n<td align=\\"left\\">Left/Right Arrows</td>\\n<td align=\\"left\\">Left/Right D-Pad</td>\\n</tr>\\n<tr>\\n<td align=\\"left\\">Shoot</td>\\n<td align=\\"left\\">X or Space</td>\\n<td align=\\"left\\">Button 1</td>\\n</tr>\\n<tr>\\n<td align=\\"left\\">Start Game</td>\\n<td align=\\"left\\">Space or Click</td>\\n<td align=\\"left\\">Button 1</td>\\n</tr>\\n</tbody>\\n</table>\\n<h2>Compiling</h2>\\n<p>This project uses the standard WASM-4 compilation system. Make sure you have the <a href=\\"https://wasm4.org/docs/getting-started/setup?code-lang=c#quickstart\\">WASM-4 tools configured</a>.</p>\\n<p>To compile the cartridge, run:</p>\\n<pre><code class=\\"language-shell\\">make\\n</code></pre>\\n<p>To run the game, use the command:</p>\\n<pre><code class=\\"language-shell\\">w4 run build/cart.wasm\\n</code></pre>"}')}}]);